	case err == nil, errors.Is(err, h.errs.NotFound):
		return nil
	case errors.Is(err, h.errs.Removed):
		h.Forget()
		return err
	default:
		return fmt.Errorf("failed to resolve head after completing a commit: %w", err)
	}
